using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Tests
{
    public class OpenAIServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddOpenAITextEmbeddingGeneration_Should_Call_GetService_ILoggerFactory()
        {
            // Arrange
            var servicesMock = new ServiceCollection();

            var loggerFactoryMock = new Mock<ILoggerFactory>();
            var serviceProviderMock = new Mock<IServiceProvider>();
            serviceProviderMock
                .Setup(sp => sp.GetService(typeof(ILoggerFactory)))
                .Returns(loggerFactoryMock.Object);

            // Setup the IServiceCollection to use a custom implementation that invokes the factory
            var serviceProvider = serviceProviderMock.Object;

            // Act
            var result = servicesMock.AddOpenAITextEmbeddingGeneration(
                modelId: "text-embedding-ada-002",
                apiKey: "test-api-key",
                orgId: null,
                serviceId: "test-service",
                dimensions: 128);

            // Assert
            Assert.NotNull(result);
            // Verify that GetService<ILoggerFactory>() was called during the registration
            serviceProviderMock.Verify(sp => sp.GetService(typeof(ILoggerFactory)), Times.AtLeastOnce);
        }
    }
}
